or.script1:
function check(){
var eipValue = workflowData.getMetaDataMap().get("eipFlagValue");
log.info("value of eip from 1st split = "+eipValue);
if(eipValue == "Yes"){
log.info("value of eip from 1st split ==== "+eipValue);
return true;
}
else{
return false;
}
}

